window.__DATA__={"date":"2024-02-07","sitting":{"date":"2024-02-07","year":2024,"n_reports":55,"n_turns":387,"n_chunks":444,"reports":55,"total_words":91757,"turns":387,"turns_covered":55},"catalog":[{"id":"motion-2310+2312+2315","title":"Advancing Mental Health","what_it_is":"Advancing Mental Health","group":"motion","sections":202,"sel_words":10636,"sentences_total":2484,"report_ids":["motion-2310","motion-2312","motion-2315"]},{"id":"motion-2316+2318","title":"Public Finances","what_it_is":"Public Finances","group":"motion","sections":152,"sel_words":8420,"sentences_total":1852,"report_ids":["motion-2316","motion-2318"]},{"id":"matter-adj-2320","title":"Building a Heat-resilient Singapore","what_it_is":"Building a Heat-resilient Singapore","group":"adjournment","sections":12,"sel_words":578,"sentences_total":133,"report_ids":["matter-adj-2320"]},{"id":"oral-answer-3440","title":"Inclusion of Tripartite Standard for Contracting with Self-Employed Persons in Reporting by SGX-listed Firms","what_it_is":"Inclusion of Tripartite Standard for Contracting with Self-Employed Persons in Reporting by SGX-listed Firms","group":"oral","sections":2,"sel_words":298,"sentences_total":14,"report_ids":["oral-answer-3440"]},{"id":"oral-answer-3431","title":"Enrolment at Polyclinics for Healthier SG","what_it_is":"Enrolment at Polyclinics for Healthier SG","group":"oral","sections":2,"sel_words":256,"sentences_total":19,"report_ids":["oral-answer-3431"]},{"id":"oral-answer-3433","title":"Standardising \"Use By\" and \"Best Before\" Date Labels for Food to Reduce Confusion","what_it_is":"Standardising \"Use By\" and \"Best Before\" Date Labels for Food to Reduce Confusion","group":"oral","sections":4,"sel_words":254,"sentences_total":38,"report_ids":["oral-answer-3433"]},{"id":"oral-answer-3430","title":"Salary Data for Child Protection Officers","what_it_is":"Salary Data for Child Protection Officers","group":"oral","sections":6,"sel_words":252,"sentences_total":40,"report_ids":["oral-answer-3430"]},{"id":"oral-answer-3429","title":"Guidelines For Schools on Setting Criteria for Direct Admission Scheme","what_it_is":"Guidelines For Schools on Setting Criteria for Direct Admission Scheme","group":"oral","sections":4,"sel_words":237,"sentences_total":55,"report_ids":["oral-answer-3429"]},{"id":"oral-answer-3442","title":"Review of Teachers' Workloads","what_it_is":"Review of Teachers' Workloads","group":"oral","sections":3,"sel_words":233,"sentences_total":22,"report_ids":["oral-answer-3442"]},{"id":"oral-answer-3435","title":"Impact of Situation in Myanmar on ASEAN's Unity","what_it_is":"Impact of Situation in Myanmar on ASEAN's Unity","group":"oral","sections":3,"sel_words":227,"sentences_total":18,"report_ids":["oral-answer-3435"]},{"id":"oral-answer-3425","title":"Compensation to Point-to-point Drivers for Downtime to Install New On-Board Units in Their Vehicles","what_it_is":"Compensation to Point-to-point Drivers for Downtime to Install New On-Board Units in Their Vehicles","group":"oral","sections":2,"sel_words":221,"sentences_total":17,"report_ids":["oral-answer-3425"]},{"id":"oral-answer-3432","title":"Teaching Students to Recognise and Report Physical, Sexual and Emotional Abuse in School Settings","what_it_is":"Teaching Students to Recognise and Report Physical, Sexual and Emotional Abuse in School Settings","group":"oral","sections":3,"sel_words":218,"sentences_total":13,"report_ids":["oral-answer-3432"]},{"id":"oral-answer-3437","title":"Introducing Separate COE Category for Point-to-Point Vehicle Services","what_it_is":"Introducing Separate COE Category for Point-to-Point Vehicle Services","group":"oral","sections":2,"sel_words":216,"sentences_total":17,"report_ids":["oral-answer-3437"]},{"id":"oral-answer-3428","title":"Assistance for Stallholders at Coffee Shops Faced with Increasing Rentals and Business Overheads","what_it_is":"Assistance for Stallholders at Coffee Shops Faced with Increasing Rentals and Business Overheads","group":"oral","sections":2,"sel_words":205,"sentences_total":38,"report_ids":["oral-answer-3428"]},{"id":"oral-answer-3426","title":"Public Education on Proper Use of Hospital A&E Departments and Promotion of Remote Care","what_it_is":"Public Education on Proper Use of Hospital A&E Departments and Promotion of Remote Care","group":"oral","sections":2,"sel_words":200,"sentences_total":20,"report_ids":["oral-answer-3426"]},{"id":"oral-answer-3434","title":"Review of Computation of Monthly CPF Interest Payment","what_it_is":"Review of Computation of Monthly CPF Interest Payment","group":"oral","sections":3,"sel_words":197,"sentences_total":23,"report_ids":["oral-answer-3434"]},{"id":"oral-answer-3441","title":"Coordinating HDB's Repairs and Redecoration Works with Town Councils' Works","what_it_is":"Coordinating HDB's Repairs and Redecoration Works with Town Councils' Works","group":"oral","sections":2,"sel_words":187,"sentences_total":15,"report_ids":["oral-answer-3441"]},{"id":"oral-answer-3443","title":"Rise in Individual Bankruptcy Applications to 18-year High","what_it_is":"Rise in Individual Bankruptcy Applications to 18-year High","group":"oral","sections":3,"sel_words":186,"sentences_total":23,"report_ids":["oral-answer-3443"]},{"id":"oral-answer-3439","title":"Universal Code for Standard of Care at Homes for Children and Adults with Disabilities, and at Day Centres for Persons with Special Needs","what_it_is":"Universal Code for Standard of Care at Homes for Children and Adults with Disabilities, and at Day Centres for Persons with Special Needs","group":"oral","sections":1,"sel_words":176,"sentences_total":7,"report_ids":["oral-answer-3439"]},{"id":"oral-answer-3427","title":"Persons with Disabilities who Applied for Jobs through Employment and Employability Institute","what_it_is":"Persons with Disabilities who Applied for Jobs through Employment and Employability Institute","group":"oral","sections":4,"sel_words":166,"sentences_total":23,"report_ids":["oral-answer-3427"]},{"id":"oral-answer-3424","title":"Preserving Heritage and Identity after Merger of Schools","what_it_is":"Preserving Heritage and Identity after Merger of Schools","group":"oral","sections":2,"sel_words":132,"sentences_total":11,"report_ids":["oral-answer-3424"]},{"id":"oral-answer-3438","title":"Success Rates for Assisted Reproductive Technology Treatments at Public Hospitals","what_it_is":"Success Rates for Assisted Reproductive Technology Treatments at Public Hospitals","group":"oral","sections":2,"sel_words":126,"sentences_total":11,"report_ids":["oral-answer-3438"]},{"id":"oral-answer-3444","title":"Statistics on Total Employment and Trade Income of Top 1,000 Earners","what_it_is":"Statistics on Total Employment and Trade Income of Top 1,000 Earners","group":"oral","sections":1,"sel_words":54,"sentences_total":6,"report_ids":["oral-answer-3444"]}],"detail":{"motion-2310+2312+2315":[{"label":"Youth mental health challenges rise","summary":"One in four young people face mental health challenges, compared to one in five in 2020.","sentences":[{"sid":"s00013","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"Notably, one in four young people face mental health challenges, as compared to one in five in 2020.","ctx":false}]},{"label":"National Mental Health and Well-being Strategy","summary":"The National Mental Health and Well-being Strategy was launched by the Inter-agency Taskforce on Mental Health and Well-being in October 2023.","sentences":[{"sid":"s00017","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"The newly introduced National Mental Health and Well-being Strategy, and henceforth, I will refer to it as \u201cthe strategy\u201d, launched by the Inter-agency Taskforce on Mental Health and Well-being in October 2023 is a commendable step forward.","ctx":false}]},{"label":"Economic cost of depression and anxiety","summary":"WHO states depression and anxiety cost the global economy $1 trillion yearly, and a Duke-NUS study found Singapore's cost is $15.7 billion annually.","sentences":[{"sid":"s00029","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"According to the World Health Organization (WHO), depression and anxiety alone cost the global economy $1 trillion per year in lost productivity.","ctx":false},{"sid":"s00030","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"In Singapore, a recent Duke-NUS Medical School study found that the economic cost of anxiety and depression is significant, amounting to $15.7 billion annually due to lost productivity and healthcare expenditure.","ctx":false}]},{"label":"Three strategic shifts in strategy","summary":"The Government outlined three strategic shifts in the strategy: a community-based strategy, empowering individuals with knowledge, and fostering inter-disciplinary collaboration.","sentences":[{"sid":"s00042","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"To achieve this, the Government outlined three strategic shifts in the strategy.","ctx":false},{"sid":"s00043","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"First, a community-based strategy; second, empowering individuals with knowledge; and third, fostering inter-disciplinary collaboration.","ctx":false}]},{"label":"Concerns about mental health services","summary":"Concerns raised included high costs, long waiting times, insurance coverage challenges, and workplace discrimination fears about being sidelined or overlooked for promotions.","sentences":[{"sid":"s00057","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"Concerns raised ranged from the high costs and long waiting times for mental health services to challenges in insurance coverage for those with mental health conditions.","ctx":false},{"sid":"s00059","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"Workplace discrimination emerged as a poignant theme, with individuals expressing fears about being sidelined or overlooked for promotions due to their mental health conditions.","ctx":false}]},{"label":"Free mental health check proposal","summary":"The speaker proposes a buy-one-get-one-free concept giving a free mental health check with every physical health screening, in line with Healthier SG.","sentences":[{"sid":"s00104","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"In line with the Healthier SG initiative, which already promotes physical health screenings, I propose an innovative, buy-one-get-one-free concept; for every physical health screening, you get a free mental health check.","ctx":false},{"sid":"s00105","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"This dual approach not only emphasises the equal importance of mental health and physical health but also offers a practical win-win solution for early detection and intervention.","ctx":false}]},{"label":"Mental health impact and time-outs","summary":"It states that mental health has physical and psychological impact, no one is immune, and time-outs without stigma must be the way forward.","sentences":[{"sid":"s00111","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"It is physical and psychological impact and the poignant fact is that no one is immune to it.","ctx":true},{"sid":"s00112","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"Thus, allowing time-outs without stigma must be the way forward for us.","ctx":false}]},{"label":"Third time triggers counsellor","summary":"It states that a person can take it twice, but a third time would automatically flag her case and require a counsellor to intervene.","sentences":[{"sid":"s00116","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"We can even allow her to take it twice.","ctx":true},{"sid":"s00117","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"However, if she takes it the third time, her case would automatically be flagged and a counsellor automatically must intervene.","ctx":false}]},{"label":"Accusations of lacking piety","summary":"It states that individuals with mental health issues are often accused of lacking piety or not praying enough, which blames them and aggravates their condition.","sentences":[{"sid":"s00132","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"Most of the time, individuals who face mental health issues are accused of lacking in piety or not performing their prayers enough.","ctx":false},{"sid":"s00133","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"Such views not only blame the ones who need help, but it also aggravates their mental health condition.","ctx":false}]},{"label":"Spirituality and other methods","summary":"It states that spirituality can be one aspect of support but cannot be the only solution, and both methods should be employed.","sentences":[{"sid":"s00137","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"While spirituality can form one aspect of support, it cannot be the only solution for complex mental health issues.","ctx":false},{"sid":"s00138","speaker":"Dr Wan Rizal (Jalan Besar)","attributed":true,"text":"To me, both are equally important and, in fact, both methods should be employed.","ctx":false}]},{"label":"Silver Ribbon anniversary attendance","summary":"It states that the speaker attended the 18th anniversary of Silver Ribbon, which was set up to combat mental health stigma through better literacy.","sentences":[{"sid":"s00158","speaker":"Mr Speaker","attributed":true,"text":"Coincidentally, last Sunday, I attended the 18th anniversary of Silver Ribbon, which was set up to combat the mental health stigma through better literacy.","ctx":false}]},{"label":"WHO mental health action plan","summary":"It states that 194 member states including Singapore signed the WHO Comprehensive Mental Health Action Plan 2013-2030, which commits them to global targets for transforming mental health.","sentences":[{"sid":"s00164","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"One hundred and ninety-four member states, including Singapore, have signed up to the WHO Comprehensive Mental Health Action Plan 2013-2030, which commits us to meet global targets for transforming mental health.","ctx":false},{"sid":"s00165","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"The plan is wide-ranging and includes ensuring that member states strengthen information systems, evidence and research for mental health to better understand the needs of the local population, ensuring that data is disaggregated by sex and age, and reflects the diverse needs of sub-populations.","ctx":false},{"sid":"s00166","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"It calls for early intervention through evidence-based psychosocial and non-farmacological interventions based in the community, avoiding institutionalisation and medicalisation.","ctx":false}]},{"label":"Quality of Life survey decline","summary":"Researchers repeated the Quality of Life survey in Singapore in 2022 and found declines in life satisfaction and well-being.","sentences":[{"sid":"s00187","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"Assoc Prof Siok Kuan Tambyah and other researchers, repeated their Quality of Life survey in Singapore in 2022 and found significant decline in Singaporean's satisfaction of life between 2016 and 2022, and a drop in overall well-being between 2011 and 2022.","ctx":false}]},{"label":"Diet and depression risk","summary":"Some studies found traditional Mediterranean and Japanese diets are linked to a 25% to 35% reduction in depression risk.","sentences":[{"sid":"s00204","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"For example, some studies have found that individuals on traditional Mediterranean and Japanese diets \u2013 which are high in vegetables, fruits, unprocessed grains, fermented foods, fish and seafood \u2013 experience a significant reduction in the risk of depression, ranging between 25% and 35%.","ctx":false}]},{"label":"Sugar labelling and sugar tax","summary":"Nutri-Grade sugar level labelling laws are a good start, and a sugar tax should be explored.","sentences":[{"sid":"s00213","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"Steps to increase awareness of and to reduce our consumption of refined sugars \u2013 which are bad for both our physical and mental health in the long-run \u2013 through the introduction of the Nutri-Grade sugar level labelling laws are a good start.","ctx":false},{"sid":"s00214","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"We should also explore the possibility of heeding WHO\u2019s calls to implement an effective sugar tax that is equitable and does not punish those on lower incomes.","ctx":false}]},{"label":"Insurer guidelines for disabilities","summary":"Regulators should ensure guidelines prohibit insurers from declining applicants based on disabilities or mental health conditions.","sentences":[{"sid":"s00228","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"In respect of the upcoming guidelines for insurers to adopt fair and responsible practices towards persons with disabilities and those with mental health conditions, our regulators should ensure that guidelines prohibit insurers from declining applications on the basis of their disabilities or mental health conditions.","ctx":false},{"sid":"s00229","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"Any differential treatment of persons with disabilities and mental health conditions should also be justified by accurate and relevant actuarial or statistical data, and there should be a mechanism by which insurers justify this.","ctx":false},{"sid":"s00230","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"Insurers should also be required to make transparent their grounds for differential treatment or rejection of applications from persons with disabilities or mental health conditions.","ctx":false}]},{"label":"Safeguards and MediSave mental health","summary":"Safeguards like mandatory background checks for those working with children should be established, and MediSave use for mental health services considered.","sentences":[{"sid":"s00235","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"We should also look to establish safeguards, such as requiring those who work with children to be subject to mandatory background checks, for the protection of vulnerable minors.","ctx":true},{"sid":"s00236","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"I hope that the Government would consider allowing the use of MediSave to access mental health services in other practice settings aside from purely psychiatric settings, particularly in the private sector.","ctx":false}]},{"label":"Parliamentary Question on insurance stigma","summary":"A Parliamentary Question was raised on young Singaporeans facing insurer stigma or being declined coverage for mental health conditions.","sentences":[{"sid":"s00249","speaker":"Dr Tan Wu Meng (Jurong)","attributed":true,"text":"Last year, on 19 September 2023, I raised a Parliamentary Question to the Minister for Health on what happens when young Singaporeans encounter stigma from insurers or are declined insurance coverage because of a mental health condition.","ctx":false},{"sid":"s00250","speaker":"Dr Tan Wu Meng (Jurong)","attributed":true,"text":"This question arose partly from a The Straits Times Forum letter earlier that year \u2013 dated 18 July 2023 \u2013 where a worried parent, Tan Hui In, shared about how their teenage daughter was turned away by two large insurance companies because of a mental health diagnosis.","ctx":false}]},{"label":"Insurance premium cliff","summary":"It states that instead of a slope of additional premiums based on incremental risks, there is a cliff people fall off when left out of the private insurance market.","sentences":[{"sid":"s00260","speaker":"Dr Tan Wu Meng (Jurong)","attributed":true,"text":"In short, instead of a slope of additional premiums based on incremental risks, there is a cliff which people fall off when they are left out from the private insurance market.","ctx":false}]},{"label":"Regulator reform for insurance","summary":"It calls on the Government to get MAS to look at insurance sector improvements and reforms, especially for young Singaporeans with mental health concerns.","sentences":[{"sid":"s00265","speaker":"Dr Tan Wu Meng (Jurong)","attributed":true,"text":"As I said during the 2020 debate on the President's Address, when the invisible hand of the market becomes unbalanced, sometimes we need the visible hand of the regulator to attain the appropriate outcome for our people, in this case, to make sure that insurance companies make decisions which are reasonable and proportionate.","ctx":true},{"sid":"s00266","speaker":"Dr Tan Wu Meng (Jurong)","attributed":true,"text":"So, I call upon this Government to get MAS on board, look at improvements and reforms to the insurance sector, especially for young Singaporeans who may be facing mental health and mental wellness concerns and young Singaporeans who may then be labelled with a diagnosis, with their whole life ahead of them.","ctx":false},{"sid":"s00267","speaker":"Dr Tan Wu Meng (Jurong)","attributed":true,"text":"Because, Mr Speaker, as I have said before in this House, healthcare is about all our lives \u2013 your life and mine.","ctx":true}]},{"label":"Depression screening for pregnant women","summary":"It states pre-COVID-19 depression rates for women and that KKH introduced depression screening for all pregnant women since early last year.","sentences":[{"sid":"s00280","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"Pre-COVID-19, post-natal depression affected one in 14 women, while pre-natal depression affected one in eight women.","ctx":false},{"sid":"s00282","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"Owing to concerns over the rise in the number of pregnant women or new mothers with depression, KK Women's and Children's Hospital (KKH) has introduced depression screening for all pregnant women since early last year.","ctx":false}]},{"label":"River Valley High School killing","summary":"It states the teenager who killed a River Valley High School student was sentenced to 16 years' imprisonment, with major depressive disorder a factor.","sentences":[{"sid":"s00289","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"Recently, the teenager who killed a River Valley High School student was sentenced to 16 years' imprisonment for his actions.","ctx":true},{"sid":"s00290","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"We have learnt through the trial proceedings that his major depressive disorder was one of three major factors that contributed to the killing.","ctx":false}]},{"label":"Teacher-counsellors deployment target","summary":"It states the Minister said MOE aims to deploy more than 1,000 teacher-counsellors in the next few years.","sentences":[{"sid":"s00300","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"The Minister also said that MOE aims to deploy more than 1,000 teacher-counsellors in the next few years.","ctx":false}]},{"label":"Four-day work week option","summary":"It states encouraging a four-day work week option for employees with mental health conditions, with pro-rated pay, to reduce stress.","sentences":[{"sid":"s00312","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"Another way is to encourage the option of four-day work week for employees with mental health conditions to reduce their stress levels and make working more manageable and sustainable.","ctx":false},{"sid":"s00313","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"This can come with a pro-rated pay, just like other part-time employees.","ctx":false}]},{"label":"Depression factor in murder","summary":"The trial showed his major depressive disorder contributed to the murder.","sentences":[{"sid":"s00328","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"During the trial, we learnt that his major depressive disorder was one of the contributing factors of the murder.","ctx":false}]},{"label":"Wage subsidy for mentally ill","summary":"The Government is asked to consider wage subsidies so employers hire individuals with mental illness.","sentences":[{"sid":"s00333","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"Could the Government consider providing wage subsidy to employers to encourage them to hire individuals with mental illness?","ctx":false}]}],"motion-2316+2318":[{"label":"Reserve accumulation and its costs","summary":"Singapore's Reserve accumulation system involves costs from Singaporeans' sacrifices, including below-market land acquisitions and CPF balances.","sentences":[{"sid":"s00002","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"The Singapore Government have put in place a good Reserve accumulation system, started by the late Dr Goh Keng Swee, to facilitate the accumulation of the huge Reserves we have today.","ctx":false},{"sid":"s00003","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"However, because our Reserves are not accumulated from natural resources, there is a cost to accumulating our Reserves, which comes from the sacrifices of the Singaporeans.","ctx":false},{"sid":"s00004","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"For example, much of the land reserves came from the acquisitions of land from Singaporeans at below market prices during the 1970s and 1980s, while the financial reserves are accumulated through the investment of land sales proceeds, Government surpluses and the Central Provident Board (CPF) balances of Singaporeans.","ctx":false}]},{"label":"Estimating financial reserves","summary":"Hazel Poa will show financial reserves can be estimated at about $1.2 trillion by deducting liabilities from financial assets.","sentences":[{"sid":"s00027","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"My colleague Ms Hazel Poa will show the House later that we can estimate our financial reserves to be about $1.2 trillion, simply by deducting the relevant liabilities from the financial assets.","ctx":false}]},{"label":"MAS accumulated new OFR","summary":"From end-2019 to end-2022, MAS accumulated about $250 billion in new OFR from large access foreign inflows.","sentences":[{"sid":"s00032","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"For example, from the end of 2019 to the end of 2022, even during the COVID-19 pandemic, MAS had accumulated new OFR from large access foreign inflows amounting to about $250 billion.","ctx":false}]},{"label":"Financial reserves generate NIR","summary":"The financial reserves currently generate NIR of about $50 billion a year.","sentences":[{"sid":"s00036","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"Currently, the financial reserves generate NIR of about $50 billion dollars a year.","ctx":false}]},{"label":"Financial reserves and investment returns","summary":"Singapore has about $1.2 trillion in financial reserves, growing yearly and generating $47 billion in fiscal 2023 investment returns.","sentences":[{"sid":"s00042","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"In summary, although not necessarily known and accepted by most Singaporeans, it is transparent to the financial markets that Singapore has approximately $1.2 trillion dollars of financial reserves, which is still growing every year and generating higher and higher investment returns each year amounting to $47 billion in fiscal year 2023.","ctx":false}]},{"label":"Budget surplus with NIRC","summary":"Total expenditures exceed operating revenues by $3 billion to $5 billion, so the budget should be in big surplus after NIRC.","sentences":[{"sid":"s00065","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"Total expenditures, which include both operating and development expenditures slightly exceeds the operating revenues by about $3 billion to $5 billion.","ctx":true},{"sid":"s00066","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"So, the budget should be in a big surplus after taking in the NIRC, which is $23.5 billion in fiscal year 2023.","ctx":false}]},{"label":"Capital transfer to endowment funds","summary":"Capital transfers to endowment and trust funds equalled 64% of NIRC from fiscal 2012 to 2020 and 72% in fiscal 2023, accumulating about $51 billion by end of fiscal 2023.","sentences":[{"sid":"s00072","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"Based on the budget figures from fiscal year 2012 to 2020, the total capital transfer to the endowment and trust funds is equivalent to 64% of the total NIRC allocated to the budget in that period.","ctx":false},{"sid":"s00073","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"In fiscal year 2023, the transfer equalled 72% of the NIRC.","ctx":false},{"sid":"s00074","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"As a result, about $51 billion has been accumulated in the 11 funds listed in the Government financial statements by the end of fiscal year 2023.","ctx":false}]},{"label":"Net spending of 11 funds","summary":"Between 2018 and 2022, actual net annual spending for the 11 funds was less than 10% of their total assets.","sentences":[{"sid":"s00080","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"Between 2018 and 2022, the actual net annual spending for the 11 funds, accounted for less than 10% of the total assets of the funds.","ctx":false}]},{"label":"HDB land cost payment","summary":"In fiscal year 2022, HDB paid about $5.39 billion of land cost to the financial reserves.","sentences":[{"sid":"s00096","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"In fiscal year 2022, the HDB paid about $5.39 billion of land cost to the financial reserves.","ctx":false}]},{"label":"HDB deficits in fiscal 2022","summary":"HDB is saddled with large deficits, which amounted to $5.38 billion in fiscal year 2022.","sentences":[{"sid":"s00099","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"As a result, HDB is saddled with large deficits, which amounted to $5.38 billion in fiscal year 2022.","ctx":false}]},{"label":"PSP first proposal on funds","summary":"PSP's first proposal is that no further endowment and trust funds should be created and no further top-ups made to existing ones.","sentences":[{"sid":"s00107","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"PSP's first proposal is that no further endowment and trust funds should be created and no further top-ups should be made to existing endowment and trust funds.","ctx":false}]},{"label":"PSP second proposal on land cost","summary":"PSP's second proposal is to waive land cost for public housing owned by Singaporeans under its affordable home scheme, which may slow reserve accumulation by up to $5 billion a year and eliminate the HDB deficit.","sentences":[{"sid":"s00116","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"PSP's second proposal is to waive the land cost for public housing owned by Singaporeans for the purpose of occupancy under the affordable home scheme, proposed by PSP.","ctx":false},{"sid":"s00118","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"Assuming the very unlikely scenario, that all Singaporeans do not sell their HDB flat, waiving land cost for public housing, may slow down the accumulation of financial reserves by up to $5 billion a year.","ctx":false},{"sid":"s00120","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"In addition, the affordable home scheme will eliminate the HDB deficit, releasing substantial resources back into the budget and reducing the tax burden of all Singaporeans, especially the middle-class Singaporeans.","ctx":false}]},{"label":"Reserves growth and fiscal space","summary":"PSP estimates reserves at $1.2 trillion with five growth sources, giving fiscal space to waive land cost for BTO pricing and delay tax rises.","sentences":[{"sid":"s00126","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"PSP has estimated that our financial reserves is about $1.2 trillion.","ctx":false},{"sid":"s00127","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"I have also explained that there are five main sources of growth for our Reserves, which will enable it to continue growing, by tens of or even, sometimes, hundreds of billions of dollars a year.","ctx":true},{"sid":"s00128","speaker":"Mr Leong Mun Wai (Non-Constituency Member)","attributed":true,"text":"This provides us, with the fiscal space to relax the pace of our Reserve accumulation marginally by, perhaps, a few billion dollars a year to waive the land cost for BTO flat pricing and, deploy the surplus budget and NIRC resources more proactively, to delay and reduce the necessity to raise taxes.","ctx":false}]},{"label":"Minimum reserves estimate","summary":"Adding Temasek assets and MAS OFR and RMGS gives a minimum financial reserves estimate of $1.09 trillion.","sentences":[{"sid":"s00137","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"The value of the assets managed by GIC is secret.","ctx":true},{"sid":"s00138","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"But, even if we only add up, the assets under Temasek and the OFR and RMGS under MAS, we get a minimum estimate of the financial reserves of $1.09 trillion.","ctx":false}]},{"label":"Reserves size range estimate","summary":"Adding GFS net assets to MAS OFR and RMGS gives $1.36 trillion, so reserves are estimated between $1.09 trillion and $1.36 trillion.","sentences":[{"sid":"s00143","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"So, by adding up the net assets under GFS, and the OFR and RMGS under MAS, we arrive at a total of $1.36 trillion.","ctx":true},{"sid":"s00144","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"Hence, we believe that the size of the financial reserves is somewhere between $1.09 trillion and $1.36 trillion.","ctx":false}]},{"label":"GIC and CPF interest gap","summary":"The 1.4 percentage point gap between GIC returns and CPF interest paid goes into the Reserves, around $7 billion yearly.","sentences":[{"sid":"s00155","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"The Minister for Manpower told us last year that CPF members earned, on average, an interest rate of close to 4%.","ctx":true},{"sid":"s00156","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"This difference between the rate of return earned by GIC and that paid to CPF members of 1.4 percentage point goes directly into the Reserves and could now be around $7 billion per year.","ctx":false}]},{"label":"Reserve accumulation retirement cost","summary":"Reserve accumulation comes at the cost of lower retirement adequacy.","sentences":[{"sid":"s00165","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"Reserve accumulation, thus, comes at the cost of lower retirement adequacy.","ctx":false}]},{"label":"Reserves versus savings survey","summary":"Estimated accumulated Reserves of $1.2 trillion are 12 times annual expenditure, while a survey shows over half of Singaporean savings are under six months of salary.","sentences":[{"sid":"s00181","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"According to our estimates, the Government accumulated Reserves have reached $1.2 trillion.","ctx":false},{"sid":"s00182","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"This is 12 times the Government's annual expenditure.","ctx":false},{"sid":"s00184","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"On the other hand, OCBC's 2023 National Financial Health Survey shows that over half of Singaporean savings are not even equivalent to six months of salary.","ctx":false}]},{"label":"New citizens and population","summary":"Without about 20,000 new citizens each year, the population will begin to shrink.","sentences":[{"sid":"s00188","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"If not for the annual intake of about 20,000 new citizens, our population will begin to shrink.","ctx":false}]},{"label":"Reserves and falling TFR","summary":"The Reserves are said to benefit children and grandchildren, but the TFR has fallen to 1.05, half the replacement rate of 2.1.","sentences":[{"sid":"s00201","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"We keep hearing that the Reserves are for the benefit of our children and grandchildren.","ctx":true},{"sid":"s00202","speaker":"Ms Hazel Poa (Non-Constituency Member)","attributed":true,"text":"But our TFR has fallen to 1.05, which is half the replacement rate of 2.1.","ctx":false}]},{"label":"Using more NIRC returns","summary":"The Government should not rule out using more than the current 50% of NIRC to lessen the taxation burden on Singaporeans.","sentences":[{"sid":"s00208","speaker":"Mr Pritam Singh (Aljunied)","attributed":true,"text":"My second point is that the Government should not rule out using more than the current 50% of NIRC or what is known as the investment returns from the Reserves, to lessen the taxation burden on Singaporeans.","ctx":false}]},{"label":"Ong Teng Cheong's 50-50 formula","summary":"The 50% figure is not sacrosanct; in the 1990s up to 100% could be spent, and Ong Teng Cheong proposed a 50-50 formula.","sentences":[{"sid":"s00229","speaker":"Mr Pritam Singh (Aljunied)","attributed":true,"text":"The 50% figure is not a sacrosanct number.","ctx":false},{"sid":"s00230","speaker":"Mr Pritam Singh (Aljunied)","attributed":true,"text":"In the 1990s, the Government was free to spend up to 100% of the interest and dividends it earned on past Reserves within a current term of government.","ctx":false},{"sid":"s00231","speaker":"Mr Pritam Singh (Aljunied)","attributed":true,"text":"When our first elected president, Ong Teng Cheong, was moved to speak on this, the late president's concern was whether the interest and dividends generated by past Reserves ought to be left fully in the hands of a current government.","ctx":true}]},{"label":"IPS working paper release","summary":"In August last year, the Institute of Policy Studies released a working paper on Singapore's fiscal policies and National Reserves.","sentences":[{"sid":"s00239","speaker":"Mr Pritam Singh (Aljunied)","attributed":true,"text":"In August last year, the Institute of Policy Studies (IPS) released a working paper titled Public Deliberation on Singapore's Fiscal Policies and National Reserves.","ctx":false}]},{"label":"IPS survey on NIR framework","summary":"The IPS working paper observed that survey respondents chose to maintain the 50-50 NIR framework, while budget game participants were more open to using more than 50%.","sentences":[{"sid":"s00244","speaker":"Mr Pritam Singh (Aljunied)","attributed":true,"text":"The IPS working paper observed that while survey respondents chose to maintain the 50-50 NIR framework, the participants in the budget game were \"more open to consider using more of the investment returns, that is, more than 50%, if these were spent in ways that would generate clear and measurable returns whether financial or social\".","ctx":false}]},{"label":"WP NIRC utilisation increase","summary":"The WP has called for increasing use of the NIRC beyond 50% when needed.","sentences":[{"sid":"s00251","speaker":"Mr Pritam Singh (Aljunied)","attributed":true,"text":"What the WP has called for is an increase in the utilisation of the NIRC beyond 50% when needed.","ctx":false}]},{"label":"WP on Reserves use","summary":"The WP does not see using 60% of the NIRC as imprudent if there are justifiable reasons.","sentences":[{"sid":"s00263","speaker":"Mr Pritam Singh (Aljunied)","attributed":true,"text":"If Mr Leong is right and the total value of our Reserves stands at $1.2 trillion dollars, COVID-19, the crisis of a generation, led to the consumption of about $40 billion, or 3.3% of our principal Reserves.","ctx":false},{"sid":"s00264","speaker":"Mr Pritam Singh (Aljunied)","attributed":true,"text":"Extrapolating from Deputy Prime Minister's reply in this House, the $40 billion amount used for \"the crisis of a generation\" was recovered in two years or less through the sale of land and NIRC contributions.","ctx":false},{"sid":"s00265","speaker":"Mr Pritam Singh (Aljunied)","attributed":true,"text":"The WP certainly does not see the depth of our Reserves as a licence for the Government to spend beyond its means or to stop the growth of our principal Reserves.","ctx":true}]}],"matter-adj-2320":[{"label":"Singapore warming and hot days","summary":"Meteorological Service reports 2013-2022 was Singapore's warmest decade, with the urban environment a significant factor, and very hot days increasing.","sentences":[{"sid":"s00005","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"The latest Meteorological Service reports says that the 10-year period, from 2013 to 2022, was Singapore's warmest on record with the man-made urban environment as a significant contributing factor.","ctx":false},{"sid":"s00006","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"The number of very hot days where daily maximum mean temperature exceeds 35\u00b0C has also increased over the last few decades and according to the third National Climate Change study, will continue to increase depending on how fast Singapore and the world decarbonises.","ctx":false}]},{"label":"Sea level protection spending","summary":"In 2019 the Government announced it may spend $100 billion or more to protect the island from rising sea levels.","sentences":[{"sid":"s00014","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"In 2019, the Government announced that it may spend $100 billion or more to protect the island from rising sea levels.","ctx":false}]},{"label":"Heat reflective paint pilot","summary":"A pilot study coated 130 Tampines HDB blocks with heat reflective paint, and subsidies are hoped for to roll it out to rental flat blocks.","sentences":[{"sid":"s00048","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"For instance, the pilot study of the 130 Tampines HDB blocks coated with heat reflective paint is a good example of a project that takes a preventive approach to increasing temperatures.","ctx":false},{"sid":"s00050","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"Given that this type of paint costs more, we hope that there can be subsidies given to roll this out to rental flat blocks if the results are promising.","ctx":false}]},{"label":"Green Building Masterplan targets","summary":"The Singapore Green Building Masterplan sets a 2030 target of 80% of buildings Green Mark-certified and an 80% energy efficiency improvement from a 2005 baseline.","sentences":[{"sid":"s00064","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"In Singapore, the Singapore Green Building Masterplan has set a 2030 target for 80% of buildings to be Green Mark-certified \u2013 80% of new developments to be super low energy and an 80% energy efficiency improvement from a 2005 baseline.","ctx":false}]},{"label":"Regulation to tackle heat","summary":"Regulation plays an important role in tackling heat, including possible legislation for MCST solar panels, climate impact assessments and free tap water at F&B establishments.","sentences":[{"sid":"s00069","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"Third, and finally, I would like to make the point that regulation plays an important role in tackling our problems with heat in Singapore.","ctx":true},{"sid":"s00070","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"These can be new things that we have not done yet, like considering the development of legislation that makes easier for condominium Management Corporations Strata Title (MCSTs) to install solar panels, which shade buildings and reduce demand for fossil fuel powered electricity.","ctx":false},{"sid":"s00071","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"We can explore the need for climate change impact assessments for new infrastructure and potentially require food and beverage (F&B) establishments to serve hydrating and healthy tap water for free.","ctx":false}]},{"label":"Water coolers at MRT stations","summary":"The Land Transport Authority could fit all MRT stations with water coolers, given Singaporeans are the world's biggest per capita spenders on bottled water.","sentences":[{"sid":"s00074","speaker":"Ms He Ting Ru (Sengkang)","attributed":true,"text":"The Land Transport Authority could also fit all Mass Rapid Transit (MRT) stations with water coolers in a quick and meaningful intervention \u2013 given that people in Singapore are the biggest spenders on bottled water in the world on a per capita basis, according to a United Nations (UN) think tank report in 2023; and this is even though our tap water is highly drinkable and well regulated.","ctx":false}]},{"label":"National heat resilience strategy","summary":"The Government adopts a science-based heat resilience strategy with three prongs: national cooling, community resilience and scientific understanding.","sentences":[{"sid":"s00082","speaker":"The Senior Minister of State for Sustainability and the Environment (Dr Amy Khor Lean Suan)","attributed":true,"text":"The Government adopts a science-based and proactive heat resilience strategy, which has three prongs: first, implementing national-level cooling strategies to benefit all segments of our society, including the vulnerable; second, strengthening the community's resilience, especially among more vulnerable population segments; and, third, deepening our scientific understanding of the impact of rising temperatures.","ctx":false}]},{"label":"Heat Stress Advisory launch","summary":"The Heat Stress Advisory was launched in July last year to guide the public on minimising heat stress risk.","sentences":[{"sid":"s00099","speaker":"The Senior Minister of State for Sustainability and the Environment (Dr Amy Khor Lean Suan)","attributed":true,"text":"Second, we have taken steps to empower the community to cope with a warming world.","ctx":true},{"sid":"s00100","speaker":"The Senior Minister of State for Sustainability and the Environment (Dr Amy Khor Lean Suan)","attributed":true,"text":"We launched the Heat Stress Advisory in July last year, to guide the public on ways to minimise the risk of heat stress.","ctx":false}]},{"label":"Rest breaks for workers","summary":"Employers must provide a minimum 10-minute hourly rest break under shade for workers doing heavy physical activities when WBGT is 32 or higher.","sentences":[{"sid":"s00113","speaker":"The Senior Minister of State for Sustainability and the Environment (Dr Amy Khor Lean Suan)","attributed":true,"text":"Of note, employers are required to provide a minimum rest break of 10 minutes hourly under shade, for workers carrying out heavy physical activities when the WBGT is 32 or higher.","ctx":false}]},{"label":"Cooling Singapore 2.0 project","summary":"The Cooling Singapore 2.0 project is developing a digital model to simulate Singapore's urban climate and assess cooling strategies.","sentences":[{"sid":"s00122","speaker":"The Senior Minister of State for Sustainability and the Environment (Dr Amy Khor Lean Suan)","attributed":true,"text":"For example, the Cooling Singapore 2.0 project is developing a digital model, to simulate Singapore's urban climate and assess the effectiveness of various cooling strategies.","ctx":false}]},{"label":"Climate Impact Science Research Programme","summary":"The Climate Impact Science Research Programme will examine rising temperatures' effects on health and second-order effects, with NUS centre as a network node.","sentences":[{"sid":"s00127","speaker":"The Senior Minister of State for Sustainability and the Environment (Dr Amy Khor Lean Suan)","attributed":true,"text":"Through the Climate Impact Science Research Programme, we will examine the effects of rising temperatures on our physical and mental health as well as second-order effects, such as increased mosquito population.","ctx":false},{"sid":"s00129","speaker":"The Senior Minister of State for Sustainability and the Environment (Dr Amy Khor Lean Suan)","attributed":true,"text":"The Heat Resilience and Performance Centre at NUS will be the Southeast Asia node of the Global Heat Health Information Network, an initiative by the World Health Organization and World Meteorological Organization.","ctx":false}]},{"label":"Time-resilient Parliament remark","summary":"Beyond a heat-resilient Singapore, the speaker says there is a time-resilient Parliament.","sentences":[{"sid":"s00133","speaker":"Mr Speaker","attributed":true,"text":"Beyond a heat-resilient Singapore, I think we do have a time-resilient Parliament.","ctx":false}]}],"oral-answer-3440":[{"label":"Tripartite Standards and ESG reporting","summary":"The Government was asked whether it will work with SGX to define Tripartite Standards as material ESG factors for listed firms' sustainability reporting.","sentences":[{"sid":"s00001","speaker":"Ms See Jinli Jean","attributed":true,"text":"asked the Prime Minister whether the Government will consider working with the Singapore Exchange (SGX) to define Tripartite Standards, such as the Tripartite Standard for Contracting with Self-Employed Persons, as a component of the material environmental, social and governance factors under SGX-listed firms' sustainability reporting.","ctx":true},{"sid":"s00002","speaker":"The Minister of State for Trade and Industry (Mr Alvin Tan) (for the Prime Minister)","attributed":true,"text":"This also applies to reporting on environmental, social and governance (ESG) factors.","ctx":false},{"sid":"s00003","speaker":"The Minister of State for Trade and Industry (Mr Alvin Tan) (for the Prime Minister)","attributed":true,"text":"Reporting requirements on such aspects are not overly prescriptive, as companies' business models, strategies and stakeholders vary widely.","ctx":false}]},{"label":"Voluntary Tripartite Standards adoption","summary":"SGX disclosure requirements promote information quality, not how companies are run, so Tripartite Standards are adopted voluntarily, with MOM and agencies encouraging adoption.","sentences":[{"sid":"s00010","speaker":"Mr Alvin Tan","attributed":true,"text":"As I mentioned earlier on, SGX disclosure requirements are, in fact, intended to promote availability and the quality of information on the companies' performance, but not to prescribe how a company should actually be run, and that is why companies adopt these Tripartite Standards on a voluntary basis.","ctx":false},{"sid":"s00011","speaker":"Mr Alvin Tan","attributed":true,"text":"I think Ms Jean See also had a similar written question to MOM.","ctx":true},{"sid":"s00012","speaker":"Mr Alvin Tan","attributed":true,"text":"That question also fleshed out how it is voluntary and how if a company has adopted the Tripartite Standards, there are certain benefits to it, including a Tripartite Standards logo, that will confer some form of additional reputational benefits to the company.","ctx":false}]}],"oral-answer-3431":[{"label":"Polyclinic and GP enrolment capacity","summary":"Average polyclinic enrolment capacity is near 30,000, 19 of 25 polyclinics have spare capacity, and Healthier SG GP clinics can enrol over 700,000 residents.","sentences":[{"sid":"s00002","speaker":"The Senior Minister of State for Health (Dr Janil Puthucheary) (for the Minister for Health)","attributed":true,"text":"The average enrolment capacity is close to 30,000 per polyclinic.","ctx":false},{"sid":"s00003","speaker":"The Senior Minister of State for Health (Dr Janil Puthucheary) (for the Minister for Health)","attributed":true,"text":"Of the 25 polyclinics, 19 polyclinics still have spare capacity to take in more enrolees; while six are reserving their capacities for their regular chronic patients to enrol, before deciding if they could take in non-regular or new residents.","ctx":false},{"sid":"s00005","speaker":"The Senior Minister of State for Health (Dr Janil Puthucheary) (for the Minister for Health)","attributed":true,"text":"A key design feature of Healthier SG is to extend the benefits of fully-subsidised preventative check-ins, health screening and vaccinations and chronic drug subsidies to private clinics.","ctx":true}]},{"label":"Polyclinic versus GP enrolment demand","summary":"65% of enrolees are with Healthier SG GP clinics; among polyclinic enrolees, 81% are existing regular patients and 19% are non-regular or new.","sentences":[{"sid":"s00012","speaker":"Dr Janil Puthucheary","attributed":true,"text":"For the first one, in terms of the relative demand, for enrolment at polyclinic versus a GP, 65% of the total that have enrolled, are enrolled with a Healthier SG GP clinic.","ctx":false},{"sid":"s00013","speaker":"Dr Janil Puthucheary","attributed":true,"text":"Among the polyclinic enrolees, 81% are existing regular patients, while the remaining 19% are non-regular and new patients.","ctx":false},{"sid":"s00014","speaker":"Dr Janil Puthucheary","attributed":true,"text":"Of the regular polyclinic patients, about 26% have enrolled with a GP clinic.","ctx":false}]}],"oral-answer-3433":[{"label":"Date-mark terms and industry compliance","summary":"Both \"use by\" and \"best before\" are internationally accepted Codex terms, and standardising to one term would add compliance burden for industry.","sentences":[{"sid":"s00002","speaker":"The Senior Minister of State for Sustainability and the Environment (Dr Koh Poh Koon) (for the Minister for","attributed":true,"text":"Sustainability and the Environment): Sir, both \"use by\" and \"best before\" are internationally accepted terms under the Codex General Standard for the Labelling of Prepackaged Foods (Codex) and commonly used by food manufacturers both locally and overseas.","ctx":false},{"sid":"s00004","speaker":"The Senior Minister of State for Sustainability and the Environment (Dr Koh Poh Koon) (for the Minister for","attributed":true,"text":"Standardising the use of date-marks to a specific term will require the industry to tailor their packaging to the Singapore market, adding to compliance burden.","ctx":false}]},{"label":"Expiry dates under food regulations","summary":"Under current food regulations, both \"use by\" and \"best before\" indicate expiry dates beyond which food cannot be sold in Singapore.","sentences":[{"sid":"s00008","speaker":"The Senior Minister of State for Sustainability and the Environment (Dr Koh Poh Koon) (for the Minister for","attributed":true,"text":"Under the current food regulations, \"use by\" and \"best before\" are both used to indicate the expiry date on food products, beyond which, the food product is not permitted to be sold in Singapore due to possible deterioration in food quality.","ctx":false}]},{"label":"Consumers must treat terms as equivalent","summary":"Asking house brands to comply to one standard will not resolve the problem, so consumers must treat both terms as equivalent.","sentences":[{"sid":"s00019","speaker":"Dr Koh Poh Koon","attributed":true,"text":"So, asking our house brands to comply to one standard will not resolve the problem.","ctx":true},{"sid":"s00020","speaker":"Dr Koh Poh Koon","attributed":true,"text":"It means that at the end of the day, the consumer must take both \"use by\" and \"best before\" as equivalent to mean that anything after that date, the food is unlikely to be fresh or may not be in its original state that is fit for consumption.","ctx":false}]},{"label":"Past dates and proper storage","summary":"Food can go bad if not stored properly even when the \"use by\" date is valid, so consumers should treat any past date as not fit for consumption.","sentences":[{"sid":"s00034","speaker":"Dr Koh Poh Koon","attributed":true,"text":"Because even if the \"use by\" date is still valid and if we do not store the food properly, the food can also go bad.","ctx":false},{"sid":"s00036","speaker":"Dr Koh Poh Koon","attributed":true,"text":"Regardless of what the \"use by\" date is, the milk may not be fit for consumption by the next day.","ctx":false},{"sid":"s00037","speaker":"Dr Koh Poh Koon","attributed":true,"text":"So, I think also some common sense is needed.","ctx":true}]}]},"report":{"report_id":"motion-2316","title":"Public Finances","n":81},"turns":[{"key":"motion-2316#t0","turn":0,"speaker":"Mr Leong Mun Wai (Non-Constituency Member)","words":3590,"proc":false,"text":"Mr Speaker, Sir, I beg to move*, \"That this House calls on the Government to review its current Budget and Reserve accumulation policies in order to help present-day Singaporeans reduce their financial burdens and improve their quality of life, while continuing to save for future generations of Singaporeans.\"   Last November, during the debate on the Cost of Living Motion raised by the Workers' Party (WP), I attributed a large part of the rising cost of living problem to the policies of the People's Action Party (PAP) Government. Today, I will delve deeper into the Government's Budget and Reserve accumulation policies to justify what I have said. The Singapore Government have put in place a good Reserve accumulation system, started by the late Dr Goh Keng Swee, to facilitate the accumulation of the huge Reserves we have today. However, because our Reserves are not accumulated from natural resources, there is a cost to accumulating our Reserves, which comes from the sacrifices of the Singaporeans. For example, much of the land reserves came from the acquisitions of land from Singaporeans at below market prices during the 1970s and 1980s, while the financial reserves are accumulated through the investment of land sales proceeds, Government surpluses and the Central Provident Board (CPF) balances of Singaporeans. Whatever the Government has accumulated in surpluses and Reserves, these are the people's money, not the Government's money. The cost of accumulating Reserves is tolerable when our economy and incomes were growing rapidly. However, as our economic fundamentals change, there comes a point when the welfare of present-day Singaporeans will be hurt if we continue accumulating Reserves at the same rate as we are doing now. We are of the view that the Singapore of today has gone past that point. The cost of living crisis that we are facing now, in addition to growing social inequality, increasing mental health issues and declining total fertility rate (TFR) are examples of social ills that have resulted from our economic policies. Today, it is not unreasonable for Singaporeans to expect the Government to focus less on accumulating Reserves and do more with our financial resources to address these social ills. However, over the years, when it comes to Reserves, the PAP Government's approach has been to tell Singaporeans that: one, there is no such thing as too much Reserves; two, that the Reserves can only be used in absolute emergencies; and three, that Singaporeans cannot be told how much Reserves we have accumulated because of national security reasons"},{"key":"motion-2316#t1","turn":1,"speaker":"Mr Speaker","words":3,"proc":false,"text":"Ms Hazel Poa."},{"key":"motion-2316#t2","turn":2,"speaker":"Ms Hazel Poa (Non-Constituency Member)","words":1557,"proc":false,"text":"Mr Speaker, PSP has raised this Motion today, because we believe that it is important for Singaporeans to have a national conversation about our Budget and Reserve accumulation policies. While we agree that there are benefits in having Reserves to cope with unforeseen circumstances, we are of the view that there comes a point, beyond which, continued accumulation of Reserves hurts the welfare of and compromises the quality of life of present-day Singaporeans. First, let me explain how we arrived at the estimate of $1.2 trillion for our financial reserves. We used two different methods. The first method is to add together the assets managed by GIC, Temasek and MAS. This method was used by CNA in the documentary, \"Singapore Reserves: The Untold Story\" in August 2023. Based on latest available figures, Temasek's net portfolio value is $382 billion. The OFR managed by MAS is $461 billion. However, this figure does not include the $247 billion of Reserves Management Government Securities (RMGS) issued when MAS transferred excess OFR to the Government. The value of the assets managed by GIC is secret. But, even if we only add up, the assets under Temasek and the OFR and RMGS under MAS, we get a minimum estimate of the financial reserves of $1.09 trillion. The second method is to use the latest Government Financial Statements (GFS). The total financial assets are $1.73 trillion, as of end-March 2023. Government borrowings totalled $1.08 trillion. Subtracting Government borrowings from total assets, we arrive at the net financial assets of $0.65 trillion. GFS does not include the assets of Statutory Boards, like MAS. So, by adding up the net assets under GFS, and the OFR and RMGS under MAS, we arrive at a total of $1.36 trillion. Hence, we believe that the size of the financial reserves is somewhere between $1.09 trillion and $1.36 trillion. We, therefore, feel that $1.2 trillion is a reasonable estimate. We, then, looked at this $1.2 trillion estimate from a third angle using the NIRC, which is half the long-term expected real investment returns. Using net investment returns of $47 billion divided by $1.2 trillion, we get a real rate of return of 3.9%, which appears to be reasonable. We have given a detailed explanation of the basis of our Reserves estimate of $1.2 trillion. If the Deputy Prime Minister and Finance Minister disputes this figure, I hope that he can explain why. Mr Speaker, my colleague, Mr Leong Mun Wai, has spoken on how land costs contribute to the growth of our Reserves. I will talk about how the higher rate of returns achieved on CPF savings"},{"key":"motion-2316#t3","turn":3,"speaker":"Mr Speaker","words":3,"proc":false,"text":"Mr Pritam Singh."},{"key":"motion-2316#t4","turn":4,"speaker":"Mr Pritam Singh (Aljunied)","words":2988,"proc":false,"text":"Mr Speaker, I will make three points concerning Singapore's Reserves and then I will set out the WP's five principles on the Reserves. My first point is that the Government should be more open about our Reserves and reveal figures not for their own sake, but so as to facilitate mature conversations on the Reserves to take place. My second point is that the Government should not rule out using more than the current 50% of NIRC or what is known as the investment returns from the Reserves, to lessen the taxation burden on Singaporeans. I note that with regard to any prospective change in the 50/50 ratio, Deputy Prime Minister Lawrence Wong is on record in this House as saying, and I quote, \"Never say never\". Although, these remarks have since been qualified to the extent that the Government does not intend to do so in the immediate term. My third point is that there is significant public belief that the Reserves are likely to be very healthy and will continue to grow through land sales. Since land sales are not used to finance the Government's Budget, the proceeds, of which, go straight to the Reserves. Mr Speaker, my first point is that the Government should be more open about our Reserves. In 2022, the WP proposed alternatives to raising the GST by considering the extent to which we can rely on the investment returns on the Reserves to fund spending needs, such as healthcare. Discussions on the Reserves are also gaining traction outside of this House. Shortly before the Presidential Elections last year, CNA broadcast a documentary which sought to shed more light on our Reserves. There were interviews with the Senior Management of MOF, the Prime Minister and former President Halimah Yacob. The Prime Minister said in the documentary that people do not appreciate the importance of the NIRC, partly because, and I quote, \"It is very hard for people to appreciate the degree to which we are benefiting from the Reserves.\" Politically, however, the conversation on utilising more of the investment returns from the Reserves as an alternative to taxation, as proposed by the WP, these have been cast by the PAP in extremely narrow terms. Almost any enquiry by the WP into the use of NIRC for social purposes, such as for intergenerational equity or as alternative levers of expenditure, is met with accusations of irresponsibility and snipes of the Opposition wanting to raid the Reserves. More recently, when the WP made requests for details about the Reserves, the PAP has characterised the Reserves as a secret weapon. One so secret that even duly elected Members of Parliam"},{"key":"motion-2316#t5","turn":5,"speaker":"Mr Speaker","words":4,"proc":false,"text":"Mr Liang Eng Hwa."},{"key":"motion-2316#t6","turn":6,"speaker":"Mr Liang Eng Hwa (Bukit Panjang)","words":2216,"proc":false,"text":"Mr Speaker, the topic of Reserves has been frequently debated in this House. We debated it in almost every Budget session or when we need to raise taxes, such as during the GST Bill; or when we need to draw down on the Reserves, such as during the COVID-19 pandemic crisis and during the Global Financial Crisis. During my tenure as a Member of Parliament so far, we have had two amendments to the Constitution related to our Reserves: first, in 2009, to institute the NIR framework; and, in 2015, when we included Temasek in the NIR framework. Both amendments have the effect of refining our spending rules which, in essence, seek to achieve Budget funding stability while also seeking to achieve intergenerational equity. These changes to the Reserves framework helped us to fulfil two purposes. Firstly, ensure that we have sufficient Reserves to deal with a major crisis or a catastrophic event, whether now or in the future. Secondly, it provides a steady and sustainable stream of income that can last across generations. Sir, in my years as a Member of this House, I have detected a significant shift in the tone of debate over the years. I remember in my first term in this House, the tone of the debate tends to be about how we can safeguard and how we can grow our Reserves. In the last decade, what I observed is that, it has since shifted more towards how we can use more of the investment returns for current spending. Sir, I supported both the constitutional amendments in 2009 and 2015 and, I agreed that the adjustment to the framework is necessary to achieve two purposes that I just mentioned. My position on the country's public finance and its Reserve accumulation policies have always been that we must stay fiscally responsible and sustainable while we tackle immediate and longer-term challenges faced by present-day Singaporeans and future generations of Singaporeans. This has been and will always be my set of personal beliefs and values. I always believe that we must live within our means, work a little harder for a better tomorrow, save a little more than we can, for better financial security not just for ourselves but for our families. I am sure many Singaporeans and Members of this House have similar values like me. They are not unique just to me. Of course, there are others who think otherwise. Sir, we can still vividly remember the pandemic and the Global Financial Crisis in 2008 and how they have impacted us. But, for me, the crisis that has the deepest bearing on me is the Asian Financial Crisis in 1997/1998. This was the crisis that had caused the meltd"},{"key":"motion-2316#t7","turn":7,"speaker":"Mr Speaker","words":8,"proc":false,"text":"Can I have a copy of your amendments?"},{"key":"motion-2316#t8","turn":8,"speaker":"Mr Liang Eng Hwa","words":10,"proc":false,"text":"Yes."},{"key":"motion-2316#t9","turn":9,"speaker":"Mr Speaker","words":14,"proc":false,"text":"The amendment is in order. Do you have copies available to distribute to Members?"},{"key":"motion-2316#t10","turn":10,"speaker":"Mr Liang Eng Hwa","words":22,"proc":false,"text":"Yes, Sir. May I request the Clerk to distribute the proposed amendments to the Members?"},{"key":"motion-2316#t11","turn":11,"speaker":"Mr Speaker","words":14,"proc":false,"text":"I think everyone has a copy. Mr Liang, you can please move your amendments."},{"key":"motion-2316#t12","turn":12,"speaker":"Mr Liang Eng Hwa","words":67,"proc":false,"text":"Mr Speaker, Sir, I beg to move the following amendments. First, in line 1, to delete \"review\" and insert \"ensure\". Second, in line 1, to delete \"current\". Third, in line 2, after the words \"Reserve accumulation policies\", to insert \"always stay fiscally responsible and sustainable,\". And fourth, in line 3, to delete \"continuing to save\" and insert \"planning and providing\". Sir, with that, I beg to move."},{"key":"motion-2316#t13","turn":13,"speaker":"Mr Speaker","words":122,"proc":false,"text":"There are four amendments proposed by Mr Liang Eng Hwa to the Motion. The first amendment is that in line 1, to delete \"review\" and insert \"ensure\". The second amendment is in line 1, to delete \"current\". The third amendment is in line 2, after the words \"Reserve accumulation policies\", to insert \"always stay fiscally responsible and sustainable,\" And the fourth amendment is in line 3, to delete \"continuing to save\" and insert \"planning and providing\". It may be convenient that the debate on the original Motion and on any other amendments moved by Members be proceeded with simultaneously as a debate on a single Question. Do I have hon Members' agreement on this?  ."},{"key":"motion-2316#t14","turn":14,"speaker":"Mr Speaker","words":26,"proc":false,"text":"The Question is the amendments as moved by Mr Liang Eng Hwa. Assoc Prof Jamus Lim. Oh, Mr Leong Mun Wai, do you have a question?"},{"key":"motion-2316#t15","turn":15,"speaker":"Mr Leong Mun Wai","words":113,"proc":false,"text":"Mr Speaker, I have one clarification for Mr Liang Eng Hwa. Can I ask Member Mr Liang Eng Hwa, during the Asian Financial Crisis or Asian Currency Crisis, which I was also deeply involved in at that time, whether the speculative attack, actually it is not just on the Singapore dollar; it was a widespread attack on all the currencies. So, there was also a sell-off on Singapore dollar, but the Singapore dollar as Mr Liang has shared, recovered very fast. So, can I ask him whether he thinks that the recovery of the Singapore dollar, at that time, was due to the fact that we have kept our financial reserves a secret?"},{"key":"motion-2316#t16","turn":16,"speaker":"Mr Liang Eng Hwa","words":138,"proc":false,"text":"Sir, I think it is a combination of factors. Of course, the financial reserves form an important consideration for the speculators not to challenge the central bank on this. Of course, like I said in my speech, the economic fundamentals of our country, how we manage the political stability and others, I think all contributed to that. But you still need to be seen to have that adequate reserve, to be able to at least set a strong first-line of defence to deter any would-be speculators from coming in. So, I believe, if you do a contrast between the countries and Singapore in the region, it would show, quite obviously, that the speculators knew they cannot challenge the Singapore central bank. Because they knew the Singapore central bank has the means to intervene and to take decisive actions."},{"key":"motion-2316#t17","turn":17,"speaker":"Mr Speaker","words":4,"proc":false,"text":"Mr Leong Mun Wai."},{"key":"motion-2316#t18","turn":18,"speaker":"Mr Leong Mun Wai","words":139,"proc":false,"text":"Mr Speaker, I have another question for Mr Liang. Does he agree that the defence of the Singapore dollar and keeping the Reserves secret are two separate matters? Because the MAS is already tasked with a lot of resources to defend the Singapore dollar and, I think, Mr Liang has quoted that during the Asian Financial Crisis, the Singapore dollar recovered very fast. I do not know, but since he was in the forex market, he may know more. How much has the Singapore MAS spent in defending Singapore at that time? Probably, $10 billion? It is not a very big sum of money, in contrast to what MAS has its arsenal to fight the speculators. So, does he agree that we do not need to keep the Reserves secret and yet we still can defend the Singapore dollar?"},{"key":"motion-2316#t19","turn":19,"speaker":"Mr Liang Eng Hwa","words":189,"proc":false,"text":"Sir, the first point is that our central bank has that credibility. Because they know it is MAS. They know they can only challenge up to a point and, they, would have to pull back. I would not know how much MAS has spent. It is not privy to me. But I know the speculators do know that it will come to a point when they will be overwhelmed by what MAS can do, given that the financial strength of Singapore, which is known. The point that Mr Leong Mun Wai is trying to say is, can we still let everyone know the size of our Reserves? I do not think it is a wise thing because once people know where our limit is, then, next time around, when they know where they can push. Maybe, more speculators, they will be going for that limit. So, I agree with the Government and, I think it makes sense for us to keep our Reserves to ourselves and not to be revealed, so that we can keep the speculators guessing. And when we intervene, we will intervene in a decisive way."},{"key":"motion-2316#t20","turn":20,"speaker":"Mr Speaker","words":4,"proc":false,"text":"Mr Leong Mun Wai."},{"key":"motion-2316#t21","turn":21,"speaker":"Mr Leong Mun Wai","words":199,"proc":false,"text":"Mr Speaker, can I ask, through you, another question for Mr Liang. The current amount of OFR that MAS has is already 100% of our GDP. Does he know how many countries in the world have OFRs equivalent to 100% of their GDP to fight the speculators? But, anyway, the Asian currency crisis, I had already proven that, actually, we have enough credibility because MAS has managed the Singapore dollar very well in line with our economic fundamentals. So, even if the speculators, as part of attacking the other Asian currencies, come and attack us, we are fully prepared because our currency is in line with our economic fundamentals. Next, we have enough OFRs to defend our currencies. So, as a result, as I said just now, is there still a need to keep the secret of our total Reserves? Because there is also some kind of contradictory argument here, on the part of Mr Liang Eng Hwa. For the speculators, the more they see what our Reserves are, the more they are unlikely to attack us. Does Mr Liang agree that keeping the total Reserves secret and defending the Singapore dollar, actually, they can be two different issues?"},{"key":"motion-2316#t22","turn":22,"speaker":"Mr Liang Eng Hwa","words":203,"proc":false,"text":"I am trying to figure out whether is that a comment or a question. I will just see how I can pick up from what the Member has just said. Firstly, I just said in my speech that the foreign exchange market is a $7 trillion market. It is massive. If there is a speculative attack, we never know what the reason is. It could be some events that happened that caused the speculative attack. Therefore, we always want to keep that last trump card to ourselves. I believe that usually works because if we reveal too much, that is when we show our hand, where our limits are. But, more importantly, the point about Singapore is that we have our inherent vulnerabilities, unlike other countries where they have a big domestic economy. They have natural resources and so on. For Singapore, we are just a tiny island-state and the financial reserves is just the only back-stop that we have. Therefore, we need to really be mindful that someone may see us as a tiny state and may, one day, find a reason to attack us. That is why keeping it not known will serve us better than to let it be known."},{"key":"motion-2316#t23","turn":23,"speaker":"Mr Speaker","words":4,"proc":false,"text":"Assoc Prof Jamus Lim."},{"key":"motion-2316#t24","turn":24,"speaker":"Assoc Prof Jamus Jerome Lim (Sengkang)","words":2682,"proc":false,"text":"What are reserves? In its broadest form, reserves are the difference between the assets and liabilities of a sovereign people. In principle, this would include not just our financial reserves, which is captured in cash and other financial assets, but all the nation's endowments: our stock of built capital, the buildings, machinery, equipment and other infrastructure; as well as our natural capital, our natural forests, reservoirs and rivers, lands and biodiversity. But, for our purpose here, we are focusing on financial reserves. In Singapore, Reserves are officially defined as the net assets of the Fifth Schedule entities in the Constitution. This includes holdings by not just our sovereign wealth funds (SWFs), GIC and Temasek, but also CPF, HDB, JTC and MAS. The bulk of these likely reside in the SWFs, with MAS also carrying a non-trivial share. Hence, for practical purposes, it makes sense for us, in this debate today, to focus on the Reserves managed by these entities. It is useful, however, to begin by asking how we even got these Reserves in the first place? We do not have many natural endowments. So, at the risk of over-simplification, it is useful to think in terms of national income accounting, which requires that any reserves we hold, or for any other country for that matter, derive from only two sources. First, from fiscal surpluses, which is, when the government collects more revenue than it spends, and it saves the remainder. The second is from current account surpluses, which result when the private sector saves more than it invests. Part of this excess saving is retained in the form of foreign currency. Money that is obtained from the sale of land or the issuance of Government securities, or SGSs, for the purposes of financial development are, therefore, forms of Reserve accumulation that derive from fiscal surpluses. The Government would like to say that such excess revenue from land is not just ours to take. Land is limited and our land endowment belongs to everybody, including future generations. Similarly, legal stipulations mean that any revenue raised from certain classes of SGSs cannot be spent on recurring expenses. But the fact remains that Reserves from this source result when there is excess saving by the Government, which means taking more income from the people than they would otherwise have been able to enjoy. In contrast, Reserves accumulated due to current account surpluses occur when the exchange rate is kept artificially low or when there is foresaving in the form, perhaps, of CPF, over and above what households may wish "},{"key":"motion-2316#t25","turn":25,"speaker":"Mr Speaker","words":3,"proc":false,"text":"Mr Neil Parekh."},{"key":"motion-2316#t26","turn":26,"speaker":"Mr Neil Parekh Nimil Rajnikant (Nominated Member)","words":1459,"proc":false,"text":"Mr Speaker, Sir, thank you for allowing me to speak on this Motion. Public finance and budgets are crucial for the Government to raise funds and simultaneously allocate those funds for national spending and fostering the development of our economy. Management of our Reserves is of great importance for Singapore, as we are a relatively small and very open economy. Many of our trading partners envy the discipline we have shown in managing and growing our Reserves over the last many years. While these countries recognise the fact that as a small and open economy, Singapore will face more volatility than larger economies with greater natural resources, they take comfort from both the professional management as well as the size of the Reserves. Additionally, the management of resources is of great importance for the entire business community in Singapore. As many of us in business know only too well, new business investment is driven by the level of confidence experienced by key decision-makers and investors at any given point of time. The way the Government responds to each crisis and the step-by-step established process taken by the executive, legislature and, finally, the President of the Republic of Singapore, has instilled great confidence in multinational corporations (MNCs), international investors and domestic companies to continue to invest in Singapore in times of trouble. As an independent Nominated Member of Parliament representing the business community, I would like to share with Members some thoughts with that lens in mind. During the COVID-19 pandemic, the Government drew down Reserves for public health expenditure, including securing of vaccines and the roll-out of stabilisation and support packages, to help workers stay employed and provide support for businesses. Such policies helped us emerge stronger when the economy recovered. Also, setting aside $150 million of Reserves to guarantee deposits was one of the measures that were instrumental in safeguarding the continuity of business operations. Without these packages, the recovery process would have been significantly impeded, adversely impacting both our entrepreneurs and Singapore's broader economic landscape. It is important to note, here, that while other countries had to borrow to initiate similar packages in their respective countries, we were able to use our Reserves to manage the crisis. In the recent past, with the high inflation hitting us, the Government has rolled out additional assurance packages, such as the Cost-of-Living Support, to ensure that Singaporeans are better able "},{"key":"motion-2316#t27","turn":27,"speaker":"Mr Speaker","words":3,"proc":false,"text":"Mr Pritam Singh."},{"key":"motion-2316#t28","turn":28,"speaker":"Mr Pritam Singh","words":203,"proc":false,"text":"Thank you, Mr Speaker. I have one question for the hon Member. I respect his views on the treatment of the NIRC and I think he gave three reasons why 50% was a figure he was comfortable with and I understand that they were long-term sustainability and prudent fiscal management. He had a final point which was the concern about expected future returns. I refer to then-Finance Minister Tharman Shanmuguratnam's round-up speech when the Constitution was amended in 2015. He talked about safeguards. The fifth safeguard and I will read what the then-Finance Minister said, and I quote, \"but there is an important fifth safeguard, which is in the governance processes in the NIR framework that also ensures that we do not spend on the basis of over-optimistic assumptions about the expected returns. The process by which expected long-term real rate of returns are decided has checks and balances and is shaped by a sense of realism about the risks in the investment world.\" In response to that, I would be grateful if the hon Member could agree with me that the way the NIRC system is designed, actually ameliorates the concern that the Member has about the expected future rates of return."},{"key":"motion-2316#t29","turn":29,"speaker":"Mr Neil Parekh Nimil Rajnikant","words":119,"proc":false,"text":"I thank the Leader of the Opposition. From what I understand, of how the returns are calculated and projected, and being in the financial markets for the last 30 years, there is no stability of financial returns, under any circumstances. There will always be volatility in the returns on any asset class, at any given point in time. One can try and smoothen out the volatility as much as one can, but that means investing everything in cash, which is obviously not a prudent thing to do, given today. In my view, the volatility in returns will remain and the expected returns will always be in a certain range, depending on the risk taken for that respective asset class."},{"key":"motion-2316#t30","turn":30,"speaker":"Mr Speaker","words":2,"proc":false,"text":"Mr Singh."},{"key":"motion-2316#t31","turn":31,"speaker":"Mr Pritam Singh","words":32,"proc":false,"text":"I thank the hon Member for his reply. My point really was that the NIR formula itself has been designed to be conservative. And that was the point I sought to make."},{"key":"motion-2316#t32","turn":32,"speaker":"Mr Speaker","words":15,"proc":false,"text":"Mr Parekh, do you want to respond? It is just a comment. Please go ahead."},{"key":"motion-2316#t33","turn":33,"speaker":"Mr Neil Parekh Nimil Rajnikant","words":13,"proc":false,"text":"Sir, I thank him for the comment. So, I will let that be."},{"key":"motion-2316#t34","turn":34,"speaker":"Mr Speaker","words":3,"proc":false,"text":"Sure. Mr Leong."},{"key":"motion-2316#t35","turn":35,"speaker":"Mr Leong Mun Wai","words":79,"proc":false,"text":"Mr Speaker, I just want to make one clarification with the hon Member Mr Neil Parekh. In his speech, he seems to have introduced a new reason for not disclosing the Reserves. I just want to confirm with him that he said, if the Reserves are revealed and they are larger than what is expected and the Government spends more, it will lead to inflation. Is he putting this up as an additional reason for not disclosing the Reserves?"},{"key":"motion-2316#t36","turn":36,"speaker":"Mr Neil Parekh Nimil Rajnikant","words":102,"proc":false,"text":"I thank the Member Mr Leong. I did, because the more money you put into the overall money supply, whether the Government spends it or any private entity spends it, it will lead to inflation if the overall pool of assets does not change. We saw that in our real estate market in the recent past, where there was a significant inflow of perhaps international money. So, absolutely. Any new money that comes in that was not there, leads to inflation \u2013 which is, perhaps, the reason that any economic policy put forward by the Government needs to be watched very carefully."},{"key":"motion-2316#t37","turn":37,"speaker":"Mr Speaker","words":2,"proc":false,"text":"Mr Leong."},{"key":"motion-2316#t38","turn":38,"speaker":"Mr Leong Mun Wai","words":77,"proc":false,"text":"Mr Speaker, Sir, I do not deny the effect of more spending, that it may have some effect on inflation. But my question is, if that is the reason the hon Member has put up for not revealing the Reserves, I would like to ask our office holders from the Government whether that is the Government's position or not. That is, I do not want to reveal the Reserves because I do not want to spend more."},{"key":"motion-2316#t39","turn":39,"speaker":"Mr Speaker","words":12,"proc":false,"text":"Actually, I think Mr Parekh mentioned that as one of a few."},{"key":"motion-2316#t40","turn":40,"speaker":"Mr Neil Parekh Nimil Rajnikant","words":75,"proc":false,"text":"Yes. If I may clarify, Speaker. What I had said, just to be very clear, is, if there is a discovery of the size of the overall Reserves which pushes the Government into extra populist policies, that will cause inflation. Meaning, the populist policies that are mandated will lead to inflation. So, that is my view. I do not think that is something that the Government can answer. They may totally disagree with my view."},{"key":"motion-2316#t41","turn":41,"speaker":"Mr Speaker","words":3,"proc":false,"text":"Mr Vikram Nair."},{"key":"motion-2316#t42","turn":42,"speaker":"Mr Vikram Nair (Sembawang)","words":2516,"proc":false,"text":"Mr Speaker, I support the amended Motion. There are two main points the original Motion made that are preserved in the amended Motion. These are: the Budget should help reduce the financial burdens of Singaporeans and improve their quality of life; the second is the Reserve accumulation policy should be adequate for future generations of Singaporeans. Both of these are good objectives. However, there is a tension between these objectives. The more we spend today, the less we will save for future generations. How do we meet both of these objectives? I believe the amendments proposed by Mr Liang Eng Hwa help to set out a principled way to strike this balance, which is to ensure that we always stay fiscally responsible and sustainable. In addition, the amendment of \"continuing to save\" is sensibly changed to \"planning and providing for\", because the stewardship of our Reserves is not passive saving but planned management to provide for the future. Let me start with the importance of building reserves. The easiest thing to do is to spend today and forget about tomorrow. There is a famous Frank Sinatra song, \"Forget Domani\". It sounds like \"Forget the money\", but actually \"domani\" is Italian for \"tomorrow\". The chorus of the song is \"Let's forget about tomorrow, for tomorrow never comes\". It is a fun song, which I enjoy listening to. But I would not rely on it to plan finances. For most countries, the need for governments to spend on ever-increasing budgets has resulted in structural deficits. These structural differences are usually financed by borrowings, such as the issue of government bonds. Over time, the amounts owed in debt continue to increase, with governments often refinancing debt when it becomes due by issuing fresh bonds. The upshot of this is that most government budgets have to provide for debt service and interest payments as the regular part of expenditure, as they continue to carry the burden of past generations while trying to spend for the current generation. Singapore has a very different starting point today. Thanks to prudent spending and management of Reserves over decades, we have built up significant Reserves. Part of the NII from these Reserves now fund our annual Budget every year. The amount this is provided has grown significantly over the years, such that it is now the largest component of our annual Budget. This means Singaporeans have the benefit of receiving more than they pay in taxes every year in Government spending, similar to other countries but without the burden of that falling on the next generation. For this benefit "},{"key":"motion-2316#t43","turn":43,"speaker":"Mr Speaker","words":2,"proc":false,"text":"Mr Singh."},{"key":"motion-2316#t44","turn":44,"speaker":"Mr Pritam Singh","words":161,"proc":false,"text":"Thank you, Mr Speaker. Just two clarifications for the hon Member. The first is with regard to a point he makes about the proposal that I made. I think my proposal was really for a Select Committee; it was not so much on the two GICs, which I believe he mentioned. What I was doing was I was quoting from a Business Times article, which I had used, to make a point during my Budget 2020 debate speech. The second point on the IPS working paper, indeed, I do not make a point which contradicts what he says. All I am saying is that the journalists and the media fell right at the bottom. And I think in his speech, he did mention that there is a lot of cynicism out there. I think those are his exact words. So, I hope he understands the context of what I had said, with regard to the point on the IPS working paper."},{"key":"motion-2316#t45","turn":45,"speaker":"Mr Speaker","words":2,"proc":false,"text":"Mr Leong."},{"key":"motion-2316#t46","turn":46,"speaker":"Mr Leong Mun Wai","words":72,"proc":false,"text":"Mr Speaker, I like to ask the hon Member Mr Vikram Nair one question. He mentioned about the tension between present-day Singaporean, or the present generation, and the future generation in terms of the use of the Reserves. Can I ask him a question how much Reserves are we accumulating every year? That means what is the rate of increase of our Reserves every year? Does he have an idea on that?"},{"key":"motion-2316#t47","turn":47,"speaker":"Mr Vikram Nair","words":22,"proc":false,"text":"I do not have the answer off-hand, but I think it can be calculated based on NIR and other forms of income."},{"key":"motion-2316#t48","turn":48,"speaker":"Mr Speaker","words":2,"proc":false,"text":"Mr Leong."},{"key":"motion-2316#t49","turn":49,"speaker":"Mr Leong Mun Wai","words":31,"proc":false,"text":"Okay. The second question I like to ask him: does he have any idea what will be the cost to the Reserves if we implement the policies that PSP has proposed?"},{"key":"motion-2316#t50","turn":50,"speaker":"Mr Vikram Nair","words":22,"proc":false,"text":"Mr Speaker, I think I have explained my disagreement with the policies in my speech. I do not propose to repeat that."},{"key":"motion-2316#t51","turn":51,"speaker":"Mr Speaker","words":2,"proc":false,"text":"Mr Leong."},{"key":"motion-2316#t52","turn":52,"speaker":"Mr Leong Mun Wai","words":60,"proc":false,"text":"Okay. Mr Speaker, so the fact is he does not know how much Reserves we are accumulating every year and he does not know how much the policies proposed by PSP would cost the Reserves. So, how does he come to the conclusion that there is a tension between the present generation and future generation, if we implement those policies?"},{"key":"motion-2316#t53","turn":53,"speaker":"Mr Vikram Nair","words":22,"proc":false,"text":"Mr Speaker, I think that is a simple point of principal. You save today, you are putting off today's consumption for tomorrow."},{"key":"motion-2316#t54","turn":54,"speaker":"Mr Speaker","words":21,"proc":false,"text":"Mr Leong, wait for me to call you before you come to the microphone. Yes, Mr Leong, you can ask now."},{"key":"motion-2316#t55","turn":55,"speaker":"Mr Leong Mun Wai","words":92,"proc":false,"text":"Mr Speaker, thank you. I understand that there is some general principles and certain things are true, the more you save, the better for the future. But, in the course of the debate, we had mentioned that there is a cost to accumulating the Reserves. So, as a result, we cannot just base our opinion on a general statement. He must know the facts. How much is being accumulated every year and how much would the policies the WP and PSP are recommending cost? I think that should be fair to say."},{"key":"motion-2316#t56","turn":56,"speaker":"Mr Speaker","words":11,"proc":false,"text":"Mr Nair, do you want to respond to that? Or \u2014"},{"key":"motion-2316#t57","turn":57,"speaker":"Mr Vikram Nair","words":144,"proc":false,"text":"I could give a simple response. Mr Speaker, I think the thrust of my speech is this. The Government and successive Governments have essentially built a nation with prudent spending. They have saved enough and the Government itself, which is the custodian of spending, is not saying it needs more money. So, to me, the real job of the Opposition and the backbench is really to be a check on Government spending because there is usually a perverse incentive for government to spend too much. So, if a government is saying that it can meet its current objectives with the current budget, there is no need to spend more. If the political Opposition is coming forward with different policies that require more spending, then it is for them to bear that onus to explain what the cost the policy is \u2013 not the Government."},{"key":"motion-2316#t58","turn":58,"speaker":"Mr Speaker","words":4,"proc":false,"text":"Assoc Prof Jamus Lim."},{"key":"motion-2316#t59","turn":59,"speaker":"Assoc Prof Jamus Jerome Lim","words":156,"proc":false,"text":"Just two clarifications from me, Mr Speaker, for Member Mr Nair. The first is that he mentioned that there is no need for the Government to raise funds for additional spending. But that my understanding is that the reason why we even raised the GST was in part because of fiscal tightness. Of course, Mr Nair does not necessarily speak for the Government, so if I could invite the Government to clarify? The second question I have is with regard to what he said about how if we have the NIRC and that is confirmed and we are not going to tap on the principal, then that is all the information we need. But surely, I am wondering if he would think that that information about the amount that is in the principal is irrelevant if we are going to talk about how much of the NIR to return, via the NIRC share, into the Reserves."},{"key":"motion-2316#t60","turn":60,"speaker":"Mr Speaker","words":7,"proc":false,"text":"Mr Nair, do you wish to respond?"},{"key":"motion-2316#t61","turn":61,"speaker":"Mr Vikram Nair","words":43,"proc":false,"text":"I do not think my response will be different from the earlier one because this is not a case where the Government is asking for more spending, saying we need to spend more. So, I do not even think I need to respond."},{"key":"motion-2316#t62","turn":62,"speaker":"Mr Speaker","words":3,"proc":false,"text":"Ms Hazel Poa."},{"key":"motion-2316#t63","turn":63,"speaker":"Ms Hazel Poa","words":87,"proc":false,"text":"I would like to clarify about the land sales proceeds. We did mention that we are proposing land sale proceeds to be treated as revenue to be divided over entire period of the lease. So, for example, if land is sold on a 99-year lease, then that land sale proceeds to be divided over 99 years as revenue and also at the end of the 99 years, the land actually reverts to the Government. So, can Mr Nair explain why that is a depletion of the principal?"},{"key":"motion-2316#t64","turn":64,"speaker":"Mr Vikram Nair","words":145,"proc":false,"text":"Mr Speaker, generally, any sale of an asset should go back into the pool of assets. Land of anything even more than 30 years, is generally considered an asset. Companies, likewise. Companies may not last 99 years, but if you sell shares in a company, that is also treated as an asset. So, the sale of land, the sale of shares that the Government may hold, all of these must go back into the asset pool of the Reserves. And, of course, any income that those assets derived can be spent as part of the NIRC. That to me is the logical way of dealing with it. I mean, this is also in accounting standards \u2013 land of more than 30 years would be regarded as an asset, so, there is not a lot of controversy in this, at least from my point of view."},{"key":"motion-2316#t65","turn":65,"speaker":"Mr Speaker","words":2,"proc":false,"text":"Ms Poa."},{"key":"motion-2316#t66","turn":66,"speaker":"Ms Hazel Poa","words":37,"proc":false,"text":"I think we need to make a distinction for land that is sold on leasehold. In the case of other assets like he mentioned, like shares, once sold is gone forever. But leasehold land returns to Government."},{"key":"motion-2316#t67","turn":67,"speaker":"Mr Speaker","words":4,"proc":false,"text":"Mr Nair? Go ahead."},{"key":"motion-2316#t68","turn":68,"speaker":"Mr Vikram Nair","words":73,"proc":false,"text":"The point about shares is just more on the lifespan. Most companies now may not even last 30 years, 40 years. So, yes, it is gone forever, but how long you would have had it, even if you kept it? So, whenever land becomes treated as an asset, say, by standard accounting standards and so on, we should also feature it as an asset. I mean, that to me is simple honest accounting."},{"key":"motion-2316#t69","turn":69,"speaker":"Mr Speaker","words":3,"proc":false,"text":"Mr Gerald Giam."},{"key":"motion-2316#t70","turn":70,"speaker":"Mr Gerald Giam Yean Song (Aljunied)","words":704,"proc":false,"text":"Mr Speaker, in our quest to safeguard the Singapore dollar, especially the volatilities of currency crises, it is important for a country to hold sufficient OFR. We have seen the dire consequences of not having enough in the tank during Thailand's ordeal in 1997. The country's struggle, stemming in part from currency speculation, led to a severe depletion of its OFR. This forced it to float its currency, triggering an economic crisis which affected the whole region, including Singapore. MAS has assessed that the \"optimal\" amount of OFR it needs to provide a \"strong buffer\" against stresses in the global economy and market is between 65% and 75% of GDP. The central bank assessed this level based on internationally-accepted measures of reserve adequacy and its own practical experience in foreign exchange intervention to ensure the stability of the Singapore dollar. Since the MAS (Amendment) Act came into force on 21 February 2022, MAS has been allowed to subscribe to the Reserves Management Government Securities (RMGS). This allows the transfer of OFR to the Government for the long-term investment by GIC. This is OFR above what MAS needs to conduct monetary policy and support financial stability. Should there be a need to supplement the OFR on MAS' balance sheet, in the instance of a tail-risk event, it can redeem the RMGS before maturity at par. Based on a Parliamentary reply by Deputy Prime Minister Lawrence Wong to me, as at September 2023, MAS' current OFR stood at $455.5 billion or 70% of GDP, with the potential to ramp it up to 106% of GDP by redeeming the RMGS holdings of $237.6 billion. This means MAS effectively has access to 31% more foreign reserves than the high-end of the range it assesses to be optimal to defend the Singapore dollar. The value of both MAS' OFR and RMGS had been revealed publicly, so has the value of Temasek Holdings' net portfolio. What remains is the value of the Reserves held by GIC, which it has only revealed is well over US$100 billion. It is estimated to be many multiples of that. In a Parliamentary reply on 3 October 2023, Deputy Prime Minister Wong said that we need to brace for extreme tail-risk scenarios, including crises of unprecedented scale that could lead to significant capital outflows beyond MAS' Reserves, or emergencies caused by state or non-state actors threatening our economy, livelihoods or national existence. Sir, the spectre of extreme scenarios cannot be a carte blanche for maintaining a veil of secrecy over our reserves. Is the Government keeping the reserves held by GIC a secret only to prepare for e"},{"key":"motion-2316#t71","turn":71,"speaker":"Mr Speaker","words":3,"proc":false,"text":"Ms Jessica Tan."},{"key":"motion-2316#t72","turn":72,"speaker":"Ms Jessica Tan Soon Neo (East Coast)","words":1465,"proc":false,"text":"Mr Speaker, thank you for the opportunity to speak on the Motion. Singapore's Reserves are critical assets and are vital for Singapore, as we have heard, many Members have already spoken about it. They are funds that Singapore can draw on during national emergencies, provide a source of investment income to finance part of the annual Government Budget and to maintain confidence in the value of the Singapore dollar through the exchange rate. But as a small country with no natural resources and an open economy, having the base of assets to provide a steady flow of funds is key to ensure that we have a base to draw on to handle emergencies for the benefit and quality of life for Singaporeans now as well as planning for the future generations. We are a little red dot and, sometimes, I worry that we forget that. We are not like many countries that have other pots of resources that they can draw on. We are not talking about just protecting the Singapore dollar. We are not talking about just protecting the currency. It is important. We have seen in recent times what has happened to countries. Things we cannot predict, on top of things in terms of natural calamities as well. So, I would like to remind the House that we are talking about the livelihoods, the lives of Singaporeans, present and the future and like Mr Liang Eng Hwa, I implore that we really take a fiscally responsible position and approach to this. As we witnessed during the COVID-19 pandemic, Singapore was able to draw on the Reserves to take decisive actions to protect and support Singaporeans. Yes, there was still pain; yes, there were still challenges. But we were able to make choices, take action quickly and ensure that we kept Singaporeans in a better position. An example is the Job Support Scheme introduced in the Unity Budget in February 2020. This provided wage support for employers. It is very important to retain local workers so that people kept their jobs. So, they kept their incomes. At the same time, companies could continue to function and, more importantly, retain their talent; and when things recover, to recover. It is not a trivial matter. If we talk about accountability, accountability is not just in how much funds we have and how we are managing the funds, but also how the funds are used and the impact it has on lives of Singaporeans. So, I really implore that everyone, let us not forget, as we talk about numbers, we are talking about people as well. The impact: the amount that was spent on JSS was about $28 billion. And a total \u2013 just to remind everyone \u2013 of an estimated 165,000"},{"key":"motion-2316#t73","turn":73,"speaker":"Mr Speaker","words":3,"proc":false,"text":"Mr Louis Chua."},{"key":"motion-2316#t74","turn":74,"speaker":"Mr Chua Kheng Wee Louis (Sengkang)","words":1437,"proc":false,"text":"Mr Speaker, my Parliamentary colleagues from the WP have set forth our party's position on the Reserves. Under the NIR framework, the Government can spend up to 50% of the long-term expected real returns on relevant assets. So, up to 50% of the net returns from the Reserves flow back to the Singapore Budget through NIRC. The estimate of NIRC is dependent on both the size of the net asset base, as well as the investment rate of return that can be expected to be earned over the long term after netting off inflation. The Leader of the Opposition, Mr Pritam Singh, has shared how we should be more open about our Reserves and reveal figures not for their own sake but so as to facilitate mature conversations on the Reserves to take place. In my view, the principles of transparency and accountability extend to not just the size of the Reserves per se but also to the investment returns generated by those charged with the responsibility. Why is this important? While the real rate of returns is, by definition, dependent on estimates of future inflation, which may not be entirely under the control of the Government, given both domestic and global factors at play, the ability to earn superior risk-adjusted returns is a key driver of NIRC and, by extension, its contributions to the Budget. As my Parliamentary colleague Assoc Prof Jamus Lim shared, our nation's Reserves belong to the people, not the Government of the day. It is important for the stewards of the Reserves to be accountable to not just the Government but to all Singaporeans, the key stakeholders of our Reserves. It is in this interest of accountability to the people or Singaporeans, that I hope that GIC will adequately disclose its detailed investment performance, both in absolute and relative terms, as well as corresponding risk analytics and on an at least annual basis, rather than merely on longer-term rolling time horizons. After all, if Temasek Holdings readily disclose such information on an annual basis, what is the justification for GIC not being able to do so? Further, it is not for the lack of such information that disclosure is not forthcoming. GIC produces quarterly and even monthly reports to the Government through the Accountant-General of Singapore containing its financial statements, detailed holdings, bank account balances, detailed performance and risk analytics, as well as the distribution of the portfolio by asset class, country and currency. In addition to ensuring there is performance accountability, I would say another important aspect of ensuring that the entities managing our Rese"},{"key":"motion-2316#t75","turn":75,"speaker":"Mr Speaker","words":45,"proc":false,"text":"Order. We have been in the Chamber for over six-and-a-half hours, so, I propose to take a break now. I suspend the Sitting and will take the Chair at 5.30 pm. Sitting accordingly suspended at 5.07 pm until 5.30 pm. Sitting resumed at 5.30 pm."},{"key":"motion-2316#t77","turn":77,"speaker":"Mr Deputy Speaker","words":3,"proc":false,"text":"Mr Saktiandi Supaat."},{"key":"motion-2316#t78","turn":78,"speaker":"Mr Saktiandi Supaat (Bishan-Toa Payoh)","words":2652,"proc":false,"text":"Mr Deputy Speaker, Sir, I rise in support of the amendments proposed by Member Mr Liang Eng Hwa. Before I proceed, I would like to declare that I am an employee of a financial institution in Singapore Singapore\u2019s prudent fiscal and Reserves policies have contributed to the progress we have seen since Independence and has created the conditions for macroeconomic stability, supported economic growth and promoted social equity. Sound and prudent fiscal policies have enabled us to build up fiscal Reserves that act as our national crisis fund and in normal times, provide a steady stream of non-tax revenue to complement our tax revenue. What the Singapore Government has gained from years of fiscal rectitude is confidence and credibility as well as the flexibility and financial resources to deal with crises, such as the one experienced in 2008/2009, and respond to longer-term challenges. As Singapore grapples with the challenges of globalisation, an ageing population and income inequality, the Government\u2019s fiscal resources as well as its capacity for constant adaptation will be critical assets. A quote by Krishna Srinivasan and Lamin Leigh, International Monetary Fund Director of the IMF's Asia and Pacific Department, and Singapore and Malaysia Mission Chief in IMF's Asia and Pacific Department, respectively, noted in the IMF's Country Focus in August 2022 that \"should further risks materialise beyond what is currently envisaged, Singapore can deploy its ample fiscal buffers to cushion the economic impact.\" Why I mention that quote is to highlight the importance of Singapore's fiscal buffers, Reserves and its prudent Budget policies that has actually put us in good stead. Going forward, Singapore is unlikely to experience the high economic growth and large fiscal surpluses of the 1990s. Instead, we face multiple challenges that will shrink our fiscal space. It is all the more important to ensure that our public finances remain sustainable to support our future progress. I would like to share, Mr Deputy Speaker, my thoughts on a few things about Singapore\u2019s fiscal policy and reserves policy approach, which I feel should stay responsible and sustainable, given our unique context both economically and constitutionally. First, our medium-term orientation, medium- to long-term focus in fiscal policy and public financing. Fiscal policy in Singapore is characterised by a strong emphasis on medium- and long-term objectives and has put us in good stead. It has evolved over time. In particular, our Reserves accumulation, which has helped us to tide through difficult time"},{"key":"motion-2316#t79","turn":79,"speaker":"Mr Deputy Speaker","words":4,"proc":false,"text":"Mr Sitoh Yih Pin."},{"key":"motion-2316#t80","turn":80,"speaker":"Mr Sitoh Yih Pin (Potong Pasir)","words":2636,"proc":false,"text":"Mr Deputy Speaker, Sir, I would like to start by quoting Mr Lee Kuan Yew. Actually, I kept this quote in my phone for a very long time and I thought, some day, I will need to use it, and I think it may be appropriate for me to use it today. Sir, in September 2011, Mr Lee Kuan Yew said, and I quote, \"I hope the Prime Minister and his Cabinet ensure that Singapore veers on the side of prudence and balance the Budget and not raid on its Reserves, which have been protected by a separately elected President. Otherwise, you have the Opposition saying, 'If you vote for me, I will give you all these things.' Where will the money come from? Not from taxes but our Reserves.\" Sir, I think Mr Lee is prescient. He said this 13 years ago and I think this is exactly what is happening today as we debate this Motion. Sir, there are two issues that the hon Members Mr Leong Mun Wai and Ms Hazel Poa have raised in their Motion. One is how we accumulate Reserves; and two, how we plan Budgets. They also acknowledge that we must save for future generations. That is a start. Let us start by talking about Budgets. Budgets are really a hit-and-miss affair, and one cannot be very accurate. Let us take Hong Kong, for example. They have the same financial year as Singapore. It runs from April to March. For the period April 2023 to March 2024, they announced in February 2023 a predicted Budget deficit of HK$54.4 billion. However, it was announced recently that in the first eight months of their financial year, the government had accumulated a deficit of HK$164 billion, three times the predicted deficit and there are another four more months to go. The lesson here is that things can turn sharply and for the worse in a world full of uncertainty and it is still better to plan and budget conservatively. Sir, I have observed, in the course of today's debate, I think the Members of the Opposition have made one very wrong assumption. They have assumed, when they talked about NIRC, that there will always be a return on capital, that whatever you invest will always give you a return. In uncertain times, such as this, this is not necessarily true because, from time to time, you can make the wrong call and your investments can be zero. But, of course, we are fortunate that we have our capable people at Temasek, GIC and MAS. From time to time, they can get it wrong, but we cannot always assume that your capital is intact. So, think about it. Do not just talk about return on capital. Talk about return of capital because you cannot assume that will always happen. Sir, the next issue I want to talk"},{"key":"motion-2316#t81","turn":81,"speaker":"Mr Deputy Speaker","words":2,"proc":false,"text":"Deputy Leader."}]};